{"type":"number"}]},"type":"array"},{"type":"null"}],"description":"Scalar for EQ/NEQ/GT/GTE/LT/LTE; a list for IN/NOT_IN; [low, high] for BETWEEN; null for IS_NULL/IS_NOT_NULL. The exact catalog data value."}},"required":["type","column","operator","value","children","child"],"type":"object"},"source_frequency":{"description":"A supported_frequencies value of the table (1D, ...; STATIC).","type":"string"},"source_table":{"description":"Catalog table.","type":"string"},"time_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"The table''s catalog time_column; null for static tables."},"time_ranges":{"description":"One or more named ranges ([] for static tables).","items":{"additionalProperties":false,"properties":{"end":{"description":"YYYY-MM-DD, last date of the range, not after the reference date; or LATEST for the newest data available (bound to the reference date; the bundle reports the actual last date). Use LATEST when the user names no end date: the catalog coverage summary can lag the newest load.","type":"string"},"range_id":{"description":"Unique within the request, e.g. current_ytd, previous_comparable.","type":"string"},"start":{"description":"YYYY-MM-DD, first date of the range.","type":"string"}},"required":["range_id","start","end"],"type":"object"},"type":"array"}},"required":["data_request_id","logical_name","source_table","entity_column","time_column","columns","scope","time_ranges","source_frequency","analysis_frequency","resample","history_buffer","future_buffer","ordering","sampling_allowed"],"type":"object"},"type":"array"},"design":{"additionalProperties":false,"description":"The analytical design the Research Plan will give this angle; the plan must repeat it unchanged.","properties":{"candidate_count":{"description":"Thresholds, lags, lengths or conditions evaluated inside this angle.","type":"integer"},"holdout_required":{"description":"True when the latest range is kept as a holdout (the angle''s requests then need at least two ranges).","type":"boolean"},"method_id":{"description":"A method of the research library (get_research_library).","enum":["conditional_distribution","threshold_sensitivity","streak_persistence","regime_comparison","cohort_comparison","quantile_ranking","lead_lag","correlation_dependency"],"type":"string"},"multiple_testing_policy":{"description":"NONE only for a single comparison.","enum":["NONE","BONFERRONI","HOLM","BENJAMINI_HOCHBERG"],"type":"string"},"outcome_horizon_periods":{"description":"Analysis periods one outcome spans.","type":"integer"},"outcome_price":{"anyOf":[{"additionalProperties":false,"properties":{"column":{"description":"The numeric price-level column (for example close) the backend computes the forward return from; never a return column.","type":"string"},"data_request_id":{"description":"The angle''s own request id (one of its data_requests) that holds the price column.","type":"string"}},"required":["data_request_id","column"],"type":"object"},{"type":"null"}],"description":"For a forward-return outcome (PERCENT or DECIMAL): the request and price column it is computed from; else null."},"outcome_unit":{"enum":["PERCENT","DECIMAL","OTHER"],"type":"string"},"pairwise_comparisons":{"type":"integer"},"parameters":{"additionalProperties":false,"description":"Every field is present; null when the angle''s method does not use it.","properties":{"baseline_mode":{"anyOf":[{"enum":["COMPLEMENT","ALL"],"type":"string"},{"type":"null"}],"description":"conditional_distribution / threshold_sensitivity: compare with the rows without the condition (COMPLEMENT) or with every row (ALL)."},"buckets":{"anyOf":[{"type":"integer"},{"type":"null"}],"description":"quantile_ranking: the number of equal-count buckets."},"comparison":{"anyOf":[{"enum":["PAIRWISE","VS_REST","FIRST_VS_OTHERS"],"type":"string"},{"type":"null"}],"description":"regime_comparison / cohort_comparison: which differences are tested."},"correlation_method":{"anyOf":[{"enum":["PEARSON","SPEARMAN"],"type":"string"},{"type":"null"}],"description":"lead_lag / correlation_dependency: the correlation."},"groups":{"anyOf":[{"items":{"type":"string"},"type":"array"},{"type":"null"}],"description":"regime_comparison / cohort_comparison: the group labels, in the order the hypothesis reads (differences are earlier minus later)."},"lags":{"anyOf":[{"items":{"type":"integer"},"type":"array"},{"type":"null"}],"description":"lead_lag: the lags tested, in analysis periods."},"primary_lag":{"anyOf":[{"type":"integer"},{"type":"null"}],"description":"lead_lag: the predeclared lag (one of lags); correlation_dependency: the lag of the main correlation (null for none)."},"rolling_window":{"anyOf":[{"type":"integer"},{"type":"null"}],"description":"correlation_dependency: the rolling window in periods, or null."},"streak_lengths":{"anyOf":[{"items":{"type":"integer"},"type":"array"},{"type":"null"}],"description":"streak_persistence: the streak lengths tested."},"threshold_operator":{"anyOf":[{"enum":[">=","<="],"type":"string"},{"type":"null"}],"description":"threshold_sensitivity: signal >= or <= each threshold."},"thresholds":{"anyOf":[{"items":{"type":"number"},"type":"array"},{"type":"null"}],"description":"threshold_sensitivity: the signal thresholds tested."}},"required":["thresholds","threshold_operator","lags","primary_lag","buckets","groups","comparison","streak_lengths","rolling_window","baseline_mode","correlation_method"],"type":"object"}},"required":["method_id","parameters","outcome_horizon_periods","outcome_unit","candidate_count","pairwise_comparisons","multiple_testing_policy","holdout_required","outcome_price"],"type":"object"},"relationships":{"description":"Catalog relationships between this angle''s requests ([] for none).","items":{"additionalProperties":false,"description":"data_need_spec/v2 (AI_ENABLE_COMPOSITE_KEYS, IP1 Stage B): a relationship names every entity key pair.","properties":{"as_of_direction":{"anyOf":[{"enum":["BACKWARD"],"type":"string"},{"type":"null"}],"description":"AS_OF only; else null."},"effective_from_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"EFFECTIVE_DATED only: catalog column; else null."},"effective_to_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"EFFECTIVE_DATED only: catalog column; else null."},"join_semantics":{"description":"One of the relationship''s supported_join_semantics in the catalog.","enum":["CURRENT_STATE","EXACT_DATE","AS_OF","EFFECTIVE_DATED"],"type":"string"},"join_type":{"description":"INNER restricts the left request to rows with a match in the right request''s scope; LEFT leaves it unrestricted. Each request is delivered as its own dataset; the analysis joins them.","enum":["INNER","LEFT"],"type":"string"},"left_columns":{"description":"Every entity key column of the catalog relationship on this side, in the order of its left_columns / right_columns without the time column (a composite key such as ticker, broker, investor_type and market_board names all of them).","items":{"type":"string"},"type":"array"},"left_request_id":{"type":"string"},"left_time_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"EXACT_DATE / AS_OF: the catalog left time column; else null."},"relationship_id":{"description":"Catalog relationship_id between the two requests'' tables.","type":"integer"},"right_columns":{"description":"The matching right-side key columns, pair by pair with left_columns.","items":{"type":"string"},"type":"array"},"right_request_id":{"type":"string"},"right_time_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"EXACT_DATE / AS_OF: the catalog right time column; else null."}},"required":["relationship_id","left_request_id","left_columns","right_request_id","right_columns","join_type","join_semantics","left_time_column","right_time_column","as_of_direction","effective_from_column","effective_to_column"],"type":"object"},"type":"array"}},"required":["angle_id","design","data_requests","relationships","broad_scope"],"type":"object"},"type":"array"},"data_as_of_policy":{"anyOf":[{"enum":["CONVERSATION","NEWEST"],"type":"string"},{"type":"null"}],"description":"Null or CONVERSATION: a range ending LATEST ends at the conversation''s data date. NEWEST only when the user asks for newer data; the answer then states both dates."},"question":{"description":"The user''s question, restated.","type":"string"},"spec_version":{"enum":["data_need_spec/v2"],"type":"string"},"subject":{"additionalProperties":false,"properties":{"asset_type":{"anyOf":[{"type":"string"},{"type":"null"}]},"data_domain":{"type":"string"},"entity_type":{"type":"string"}},"required":["data_domain","entity_type","asset_type"],"type":"object"},"time_basis":{"description":"HISTORICAL_DESCRIPTIVE (normal) or POINT_IN_TIME (as known then).","enum":["HISTORICAL_DESCRIPTIVE","POINT_IN_TIME"],"type":"string"}},"required":["spec_version","question","subject","angles","data_as_of_policy","time_basis"],"type":"object"}',
     'Before presenting a multi-angle Research Plan, check every angle''s design and data. Send one entry per planned angle: angle_id, its design (method from get_research_library, parameters, horizon, unit, comparisons, multiple-testing policy, holdout, and for a forward-return outcome the request and price column) and its DataNeedSpec v2 data_requests and relationships in the angle''s own ids. The backend checks each design against the method''s rules and data requirements, merges equal requests of different angles into one bundle when they fit, splits the angles into a few bundle groups only when they do not, validates each group and estimates its extraction without reading data. Returns FEASIBLE with the bundle groups, each angle''s bundle request and range ids and the columns it may use (its data contract); NOT_FEASIBLE naming the angles that cannot be served; or REVISION_REQUIRED with issues by angle. When the question names specific entities (for example BBCA), each request reads only those entities (a scope predicate on its entity column); a request that must read every entity (a market benchmark, a cross-section) is declared in that angle''s broad_scope with the reason. Present the plan only after FEASIBLE, with exactly the angles and designs checked.')
) AS next(name, from_version, version, input_schema, purpose)
  ON previous.tool_name = next.name AND previous.version = next.from_version;

DO $verify$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE NOT is_active AND ((tool_name = 'submit_data_need_spec' AND version = 'v8') OR (tool_name = 'check_data_feasibility' AND version = 'v6') OR (tool_name = 'check_research_feasibility' AND version = 'v5'))) <> 3 THEN
        RAISE EXCEPTION 'The phase C tool versions were not registered';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'submit_data_need_spec' AND version = 'v8' AND input_schema::text LIKE '%data_as_of_policy%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'check_data_feasibility' AND version = 'v6' AND input_schema::text LIKE '%data_as_of_policy%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'check_research_feasibility' AND version = 'v5' AND input_schema::text LIKE '%data_as_of_policy%') THEN
        RAISE EXCEPTION 'The phase C contracts are not in the registered rows';
    END IF;
END
$verify$;

COMMIT;
